/**
 * CreateProjectModal (Wizard Version)
 * 
 * Multi-step wizard for creating new AI video projects.
 * Steps: Story ΓåÆ Settings ΓåÆ Confirm
 */
import { useTranslation } from 'react-i18next';
import { AnimatePresence, motion } from 'framer-motion';
import { Modal, Button, GradientText } from '@superapp/ui-kit';
import { useProjectWizard } from '@/hooks';
import { 
  StepIndicator, 
  StoryInputStep, 
  SettingsStep, 
  ConfirmStep 
} from './wizard';
import { ArrowLeft, ArrowRight, Sparkles, Loader2 } from 'lucide-react';

interface CreateProjectModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const stepVariants = {
  enter: { opacity: 0, x: 20 },
  center: { opacity: 1, x: 0 },
  exit: { opacity: 0, x: -20 },
};

export const CreateProjectModal = ({ open, onOpenChange }: CreateProjectModalProps) => {
  const { t } = useTranslation(['video_projects', 'uikit']);
  
  const {
    currentStep,
    data,
    isSubmitting,
    error,
    nextStep,
    prevStep,
    canGoNext,
    canGoPrev,
    updateData,
    resetWizard,
    submitProject,
    getPlatformDefaults,
    goToStep,
  } = useProjectWizard();

  const handleClose = () => {
    onOpenChange(false);
    // Delay reset to avoid visual glitch
    setTimeout(resetWizard, 300);
  };

  const getStepTitle = () => {
    switch (currentStep) {
      case 'story': return t('video_projects:wizard.title_story');
      case 'settings': return t('video_projects:wizard.title_settings');
      case 'confirm': return t('video_projects:wizard.title_confirm');
    }
  };

  const getStepDescription = () => {
    switch (currentStep) {
      case 'story': return t('video_projects:wizard.desc_story');
      case 'settings': return t('video_projects:wizard.desc_settings');
      case 'confirm': return t('video_projects:wizard.desc_confirm');
    }
  };

  return (
    <Modal
      isOpen={open}
      onClose={handleClose}
      title={
        <span className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-primary" />
          {getStepTitle()}
        </span>
      }
      description={getStepDescription()}
      size="lg"
      footer={
        <div className="flex justify-between w-full items-center">
          <div>
            {canGoPrev && (
              <Button 
                type="button" 
                variant="ghost" 
                onClick={prevStep}
                className="gap-2"
              >
                <ArrowLeft size={16} /> {t('uikit:back')}
              </Button>
            )}
          </div>
          <div className="flex gap-2">
            <Button 
              type="button" 
              variant="outline" 
              onClick={handleClose}
            >
              {t('uikit:cancel')}
            </Button>
            
            {currentStep === 'confirm' ? (
              <Button 
                onClick={submitProject}
                loading={isSubmitting}
                className="gap-2"
              >
                <Sparkles size={16} />
                {t('video_projects:wizard.create_project')}
              </Button>
            ) : (
              <Button 
                onClick={nextStep}
                className="gap-2"
              >
                {t('uikit:next')} <ArrowRight size={16} />
              </Button>
            )}
          </div>
        </div>
      }
    >
      {/* Step Indicator */}
      <StepIndicator 
        currentStep={currentStep} 
        onStepClick={goToStep}
      />

      {/* Step Content with Animation */}
      <AnimatePresence mode="wait">
        <motion.div
          key={currentStep}
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
          transition={{ duration: 0.2 }}
          className="min-h-[300px]"
        >
          {currentStep === 'story' && (
            <StoryInputStep 
              data={data} 
              onUpdate={updateData} 
              error={error}
            />
          )}
          {currentStep === 'settings' && (
            <SettingsStep 
              data={data} 
              onUpdate={updateData}
              getPlatformDefaults={getPlatformDefaults}
            />
          )}
          {currentStep === 'confirm' && (
            <ConfirmStep data={data} />
          )}
        </motion.div>
      </AnimatePresence>
    </Modal>
  );
};

/**
 * ConfirmStep Component
 * 
 * Final step: Review and confirm project creation.
 */
import { useTranslation } from 'react-i18next';
import { 
  Card, 
  CardContent, 
  CardHeader, 
  CardTitle,
  Badge
} from '@superapp/ui-kit';
import type { WizardData } from '@/hooks/useProjectWizard';
import { PLATFORM_PRESETS } from '@/types';
import { FileText, Settings, Clock, Monitor, Smartphone, Square } from 'lucide-react';

interface ConfirmStepProps {
  data: WizardData;
}

const AspectIcon = ({ ratio }: { ratio: string }) => {
  switch (ratio) {
    case '9:16': return <Smartphone className="w-4 h-4" />;
    case '16:9': return <Monitor className="w-4 h-4" />;
    default: return <Square className="w-4 h-4" />;
  }
};

export const ConfirmStep = ({ data }: ConfirmStepProps) => {
  const { t } = useTranslation(['video_projects']);
  const platformPreset = PLATFORM_PRESETS[data.targetPlatform];

  return (
    <div className="space-y-4">
      <p className="text-muted-foreground text-center mb-6">
        {t('video_projects:wizard.confirm.review_message')}
      </p>

      {/* Project Info */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-base">
            <FileText className="w-4 h-4" />
            {t('video_projects:wizard.confirm.project_info')}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-2 text-sm">
          <div className="flex justify-between">
            <span className="text-muted-foreground">{t('video_projects:wizard.story.name_label')}:</span>
            <span className="font-medium">{data.name}</span>
          </div>
          {data.description && (
            <div className="flex justify-between">
              <span className="text-muted-foreground">{t('video_projects:wizard.story.desc_label')}:</span>
              <span className="font-medium truncate max-w-[200px]">{data.description}</span>
            </div>
          )}
          <div className="pt-2 border-t">
            <span className="text-muted-foreground">{t('video_projects:wizard.story.content_label')}:</span>
            <p className="mt-1 text-sm bg-muted/50 p-2 rounded-md line-clamp-3">
              {data.storyContent}
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Settings Info */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-base">
            <Settings className="w-4 h-4" />
            {t('video_projects:wizard.confirm.settings_info')}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3 text-sm">
          <div className="flex justify-between items-center">
            <span className="text-muted-foreground">{t('video_projects:wizard.settings.platform_label')}:</span>
            <Badge variant="secondary">
              {data.targetPlatform === 'tiktok' && '≡ƒô▒ TikTok'}
              {data.targetPlatform === 'youtube_shorts' && 'Γû╢∩╕Å YouTube Shorts'}
              {data.targetPlatform === 'instagram_reels' && '≡ƒô╕ Instagram Reels'}
              {data.targetPlatform === 'generic' && '≡ƒÄ¼ Generic'}
            </Badge>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-muted-foreground">{t('video_projects:wizard.settings.aspect_label')}:</span>
            <span className="flex items-center gap-1 font-medium">
              <AspectIcon ratio={data.aspectRatio} />
              {data.aspectRatio}
            </span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-muted-foreground">{t('video_projects:wizard.settings.duration_label')}:</span>
            <span className="flex items-center gap-1 font-medium">
              <Clock className="w-4 h-4" />
              {data.targetDuration}s
            </span>
          </div>
        </CardContent>
      </Card>

      {/* Next Steps Info */}
      <div className="bg-green-50 dark:bg-green-950/30 p-4 rounded-lg border border-green-100 dark:border-green-900/50">
        <h4 className="font-semibold text-green-700 dark:text-green-300 mb-2">
          {t('video_projects:wizard.confirm.next_steps_title')}
        </h4>
        <ol className="text-sm text-green-600 dark:text-green-400 space-y-1 list-decimal list-inside">
          <li>{t('video_projects:wizard.confirm.next_step1')}</li>
          <li>{t('video_projects:wizard.confirm.next_step2')}</li>
          <li>{t('video_projects:wizard.confirm.next_step3')}</li>
        </ol>
      </div>
    </div>
  );
};

/**
 * SettingsStep Component
 * 
 * Second step of wizard: Platform, aspect ratio, and duration settings.
 */
import { useTranslation } from 'react-i18next';
import { 
  FormItem, 
  FormLabel, 
  FormDescription,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Slider,
  Card,
  CardContent
} from '@superapp/ui-kit';
import { 
  type WizardData, 
  type UseProjectWizardReturn 
} from '@/hooks/useProjectWizard';
import { 
  TARGET_PLATFORM, 
  ASPECT_RATIO, 
  PLATFORM_PRESETS,
  type TargetPlatform,
  type AspectRatio
} from '@/types';
import { Monitor, Smartphone, Square } from 'lucide-react';

interface SettingsStepProps {
  data: WizardData;
  onUpdate: (partial: Partial<WizardData>) => void;
  getPlatformDefaults: UseProjectWizardReturn['getPlatformDefaults'];
}

const PLATFORM_OPTIONS = [
  { value: TARGET_PLATFORM.TIKTOK, label: 'TikTok', icon: '≡ƒô▒' },
  { value: TARGET_PLATFORM.YOUTUBE_SHORTS, label: 'YouTube Shorts', icon: 'Γû╢∩╕Å' },
  { value: TARGET_PLATFORM.INSTAGRAM_REELS, label: 'Instagram Reels', icon: '≡ƒô╕' },
  { value: TARGET_PLATFORM.GENERIC, label: 'Generic Video', icon: '≡ƒÄ¼' },
];

const ASPECT_OPTIONS = [
  { value: ASPECT_RATIO.PORTRAIT_9_16, label: '9:16 (Portrait)', icon: Smartphone },
  { value: ASPECT_RATIO.LANDSCAPE_16_9, label: '16:9 (Landscape)', icon: Monitor },
  { value: ASPECT_RATIO.SQUARE_1_1, label: '1:1 (Square)', icon: Square },
];

export const SettingsStep = ({ data, onUpdate, getPlatformDefaults }: SettingsStepProps) => {
  const { t } = useTranslation(['video_projects']);
  
  const currentPlatformPreset = PLATFORM_PRESETS[data.targetPlatform];

  const handlePlatformChange = (platform: TargetPlatform) => {
    const defaults = getPlatformDefaults(platform);
    onUpdate({
      targetPlatform: platform,
      aspectRatio: defaults.aspectRatio,
      targetDuration: defaults.targetDuration,
    });
  };

  return (
    <div className="space-y-6">
      {/* Platform Selection */}
      <FormItem>
        <FormLabel>{t('video_projects:wizard.settings.platform_label')}</FormLabel>
        <Select 
          value={data.targetPlatform} 
          onValueChange={(v) => { handlePlatformChange(v as TargetPlatform); }}
        >
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {PLATFORM_OPTIONS.map((opt) => (
              <SelectItem key={opt.value} value={opt.value}>
                <span className="flex items-center gap-2">
                  <span>{opt.icon}</span>
                  <span>{opt.label}</span>
                </span>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <FormDescription>
          {t('video_projects:wizard.settings.platform_hint')}
        </FormDescription>
      </FormItem>

      {/* Aspect Ratio */}
      <FormItem>
        <FormLabel>{t('video_projects:wizard.settings.aspect_label')}</FormLabel>
        <div className="grid grid-cols-3 gap-3">
          {ASPECT_OPTIONS.map((opt) => {
            const Icon = opt.icon;
            const isSelected = data.aspectRatio === opt.value;
            return (
              <button
                key={opt.value}
                type="button"
                onClick={() => { onUpdate({ aspectRatio: opt.value as AspectRatio }); }}
                className={`
                  p-4 rounded-lg border-2 transition-all text-center
                  ${isSelected 
                    ? 'border-primary bg-primary/10 text-primary' 
                    : 'border-muted hover:border-primary/50'}
                `}
              >
                <Icon className="w-6 h-6 mx-auto mb-2" />
                <span className="text-sm font-medium">{opt.label}</span>
              </button>
            );
          })}
        </div>
      </FormItem>

      {/* Duration Slider */}
      <FormItem>
        <FormLabel>
          {t('video_projects:wizard.settings.duration_label')}: {data.targetDuration}s
        </FormLabel>
        <Slider
          value={[data.targetDuration]}
          onValueChange={([v]) => { onUpdate({ targetDuration: v }); }}
          min={currentPlatformPreset.minDuration}
          max={currentPlatformPreset.maxDuration}
          step={5}
          className="mt-2"
        />
        <FormDescription>
          {t('video_projects:wizard.settings.duration_hint', {
            min: currentPlatformPreset.minDuration,
            max: currentPlatformPreset.maxDuration,
          })}
        </FormDescription>
      </FormItem>

      {/* Platform Notes */}
      {currentPlatformPreset.notes && (
        <Card className="bg-amber-50 dark:bg-amber-950/30 border-amber-200 dark:border-amber-800">
          <CardContent className="p-4">
            <p className="text-sm text-amber-700 dark:text-amber-300">
              ≡ƒÆí <strong>{t('video_projects:wizard.settings.platform_tip')}:</strong>{' '}
              {currentPlatformPreset.notes}
            </p>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

/**
 * StepIndicator Component
 * 
 * Visual indicator showing wizard progress.
 */
import { Check } from 'lucide-react';
import { cn } from '@superapp/ui-kit';
import { useTranslation } from 'react-i18next';
import type { WizardStep } from '@/hooks/useProjectWizard';

interface StepIndicatorProps {
  currentStep: WizardStep;
  onStepClick?: (step: WizardStep) => void;
}

const STEPS: { key: WizardStep; labelKey: string }[] = [
  { key: 'story', labelKey: 'video_projects:wizard.steps.story' },
  { key: 'settings', labelKey: 'video_projects:wizard.steps.settings' },
  { key: 'confirm', labelKey: 'video_projects:wizard.steps.confirm' },
];

export const StepIndicator = ({ currentStep, onStepClick }: StepIndicatorProps) => {
  const { t } = useTranslation(['video_projects']);
  const currentIndex = STEPS.findIndex(s => s.key === currentStep);

  return (
    <div className="flex items-center justify-center gap-2 mb-6">
      {STEPS.map((step, index) => {
        const isCompleted = index < currentIndex;
        const isCurrent = index === currentIndex;
        const isClickable = onStepClick && index < currentIndex;

        return (
          <div key={step.key} className="flex items-center">
            {/* Step Circle */}
            <button
              type="button"
              onClick={() => isClickable && onStepClick(step.key)}
              disabled={!isClickable}
              className={cn(
                'w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-all',
                isCompleted && 'bg-primary text-primary-foreground',
                isCurrent && 'bg-primary/20 text-primary border-2 border-primary animate-pulse',
                !isCompleted && !isCurrent && 'bg-muted text-muted-foreground',
                isClickable && 'cursor-pointer hover:scale-110'
              )}
            >
              {isCompleted ? <Check size={16} /> : index + 1}
            </button>
            
            {/* Step Label */}
            <span
              className={cn(
                'ml-2 text-sm hidden sm:inline',
                isCurrent && 'font-semibold text-foreground',
                !isCurrent && 'text-muted-foreground'
              )}
            >
              {t(step.labelKey)}
            </span>
            
            {/* Connector Line */}
            {index < STEPS.length - 1 && (
              <div
                className={cn(
                  'w-8 sm:w-12 h-0.5 mx-2',
                  index < currentIndex ? 'bg-primary' : 'bg-muted'
                )}
              />
            )}
          </div>
        );
      })}
    </div>
  );
};
